create table products (id uuid primary key, name varchar(160) not null, slug varchar(160) not null unique, short_description varchar(500) not null, description text not null, category varchar(100) not null, image_url varchar(500), featured boolean not null default false, status varchar(20) not null default 'DRAFT', display_order integer not null default 0, features text not null default '');
create table pricing_packages (id uuid primary key, product_id uuid not null references products(id), name varchar(120) not null, description varchar(500) not null, price numeric(19,2), currency varchar(8) not null, billing_frequency varchar(20) not null, custom_price boolean not null default false, active boolean not null default true, featured boolean not null default false, display_order integer not null default 0, features text not null default '');
create table services (id uuid primary key, name varchar(160) not null, slug varchar(160) not null unique, short_description varchar(500) not null, description text not null, status varchar(20) not null default 'DRAFT', display_order integer not null default 0);
create table inquiries (id uuid primary key, reference_number varchar(32) not null unique, full_name varchar(160) not null, email varchar(254) not null, phone varchar(40), company varchar(160), subject varchar(120) not null, product_id uuid references products(id), message text not null, status varchar(20) not null default 'NEW', notes text, created_at timestamp with time zone not null default now());
create table demo_requests (id uuid primary key, reference_number varchar(32) not null unique, full_name varchar(160) not null, company_name varchar(160) not null, email varchar(254) not null, phone varchar(40) not null, product_id uuid not null references products(id), preferred_date varchar(20), preferred_time varchar(20), business_type varchar(120), additional_information text, status varchar(20) not null default 'PENDING', notes text, created_at timestamp with time zone not null default now());
create table company_settings (setting_key varchar(120) primary key, setting_value text not null);
create table users (id uuid primary key, email varchar(254) not null unique, password_hash varchar(100) not null, role varchar(40) not null, active boolean not null default true);
create table audit_logs (id uuid primary key, actor varchar(254) not null, action varchar(100) not null, entity_id uuid, created_at timestamp with time zone not null default now());
create index idx_products_status on products(status, display_order);
create index idx_packages_product on pricing_packages(product_id, active);
create index idx_inquiries_status on inquiries(status, created_at);
create index idx_demos_status on demo_requests(status, created_at);
